134	/// Returns the [TextRange] of the hook name; the node of the
135	/// expression of the argument that correspond to the closure of
136	/// the hook; and the node of the dependency list of the hook.
137	///
138	/// Example:
139	/// ```js
140	/// useEffect(() => {}, []);
141	///                     ^^ <- dependencies_node
142	///           ^^^^^^^^ <- closure_node
143	/// ^^^^^^^^^ <- function_name_range
144	/// ```
145	///
146	/// This function will use the parameter "hooks" with the configuration
147	/// of all function that are considered hooks. See [ReactHookConfiguration].
148	pub(crate) fn react_hook_with_dependency(
149	    call: &JsCallExpression,
150	    hooks: &FxHashMap<String, ReactHookConfiguration>,
151	    model: &SemanticModel,
152	) -> Option<ReactCallWithDependencyResult> {
153	    let expression = call.callee().ok()?;
154	    let name = if let Some(identifier) = expression.as_js_reference_identifier() {
155	        Some(StaticValue::String(identifier.value_token().ok()?))
156	    } else if let Some(member_expr) = AnyJsMemberExpression::cast_ref(expression.syntax()) {
157	        Some(member_expr.member_name()?)
158	    } else {
159	        None
160	    }?;
161	    let function_name_range = name.range();
162	    let name = name.text();
163	
164	    // check if the hooks api is imported from the react library
165	    if HOOKS_WITH_DEPS_API.contains(&name)
166	        && !is_react_call_api(expression, model, ReactLibrary::React, name)
167	    {
168	        return None;
169	    }
170	
171	    let hook = hooks.get(name)?;
172	    let closure_index = hook.closure_index?;
173	    let dependencies_index = hook.dependencies_index?;
174	
175	    let mut indices = [closure_index, dependencies_index];
176	    indices.sort_unstable();
177	    let [closure_node, dependencies_node] = call.arguments().ok()?.get_arguments_by_index(indices);
178	
179	    Some(ReactCallWithDependencyResult {
180	        function_name_range,
181	        closure_node: closure_node.and_then(|x| x.as_any_js_expression().cloned()),
182	        dependencies_node: dependencies_node.and_then(|x| x.as_any_js_expression().cloned()),
183	    })
184	}
