107	/// Determines whether the given `node` is executed conditionally due to the
108	/// position it takes within its `parent_node`.
109	///
110	/// Returns `true` if and only if the parent node is a node that introduces a
111	/// condition that makes execution of `node` conditional.
112	///
113	/// Generally, this means that for conditional expressions, the "test" is
114	/// considered unconditional (since it is always evaluated), while the branches
115	/// are considered conditional.
116	///
117	/// For example:
118	///
119	/// ```js
120	///    testNode ? truthyNode : falsyNode
121	/// // ^^^^^^^^---------------------------- This node is always executed.
122	/// //            ^^^^^^^^^^---^^^^^^^^^--- These nodes are conditionally executed.
123	/// ```
124	fn is_conditional_expression(
125	    parent_node: &SyntaxNode<JsLanguage>,
126	    node: &SyntaxNode<JsLanguage>,
127	) -> bool {
128	    if let Some(assignment_with_default) = JsAssignmentWithDefault::cast_ref(parent_node) {
129	        return assignment_with_default
130	            .default()
131	            .is_ok_and(|default| default.syntax() == node);
132	    }
133	
134	    if let Some(binding_pattern_with_default) = JsBindingPatternWithDefault::cast_ref(parent_node) {
135	        return binding_pattern_with_default
136	            .default()
137	            .is_ok_and(|default| default.syntax() == node);
138	    }
139	
140	    if let Some(conditional_expression) = JsConditionalExpression::cast_ref(parent_node) {
141	        return conditional_expression
142	            .test()
143	            .is_ok_and(|test| test.syntax() != node);
144	    }
145	
146	    if let Some(if_statement) = JsIfStatement::cast_ref(parent_node) {
147	        return if_statement.test().is_ok_and(|test| test.syntax() != node);
148	    }
149	
150	    if let Some(logical_expression) = JsLogicalExpression::cast_ref(parent_node) {
151	        return logical_expression
152	            .right()
153	            .is_ok_and(|right| right.syntax() == node);
154	    }
155	
156	    if let Some(object_binding_pattern_shorthand_property) =
157	        JsObjectBindingPatternShorthandProperty::cast_ref(parent_node)
158	    {
159	        return object_binding_pattern_shorthand_property
160	            .init()
161	            .is_some_and(|init| init.syntax() == node);
162	    }
163	
164	    if let Some(try_finally_statement) = JsTryFinallyStatement::cast_ref(parent_node) {
165	        // Code inside `try` statements is considered conditional, because a
166	        // thrown error is expected at any point, so there's no guarantee
167	        // whether code will run unconditionally. But we make an exception for
168	        // the `finally` clause since it does run unconditionally.
169	        //
170	        // Note: Of course code outside a `try` block may throw too, but then
171	        // the exception will bubble up and break the entire component, instead
172	        // of being merely a violation of the rules of hooks.
173	        return try_finally_statement
174	            .finally_clause()
175	            .is_ok_and(|finally_clause| finally_clause.syntax() != node);
176	    }
177	
178	    // The following statement kinds are considered to always make their inner
179	    // nodes conditional:
180	    matches!(
181	        parent_node.kind(),
182	        JsSyntaxKind::JS_DO_WHILE_STATEMENT
183	            | JsSyntaxKind::JS_FOR_IN_STATEMENT
184	            | JsSyntaxKind::JS_FOR_OF_STATEMENT
185	            | JsSyntaxKind::JS_FOR_STATEMENT
186	            | JsSyntaxKind::JS_SWITCH_STATEMENT
187	            | JsSyntaxKind::JS_TRY_STATEMENT
188	            | JsSyntaxKind::JS_WHILE_STATEMENT
189	    )
190	}
