///
/// This is used to identify the top-level boundary from which hooks are allowed
/// to be called. It intentionally accepts components and hooks that are defined
/// inside other functions (such as inside a test body), since those are still
/// legitimate top-level boundaries for their own hook calls.
fn is_react_component_or_hook(function: &AnyJsFunctionOrMethod) -> bool {
    function_or_method_name(function).is_some_and(|name| {
        let name = name.text();
        is_react_component(name) || is_react_hook(name)
